package piglatin

import "strings"

// Sentence translates a sentence from English to Pig Latin.
func Sentence(sentence string) string {
	words := strings.Fields(sentence)
	for i, w := range words {
		words[i] = word(w)
	}
	return strings.Join(words, " ")
}

// word translates a single word to Pig Latin.
func word(w string) string {
	n := len(w)
	if n == 0 {
		return w
	}
	// Rule 1: starts with a vowel, "xr", or "yt".
	if isVowel(w[0]) || strings.HasPrefix(w, "xr") || strings.HasPrefix(w, "yt") {
		return w + "ay"
	}
	// Find the end of the leading consonant cluster.
	// Rule 3: a "qu" inside the cluster is moved along with it.
	// Rule 4: a "y" (not in first position) ends the cluster.
	split := n
	for i := 0; i < n; i++ {
		c := w[i]
		if c == 'q' && i+1 < n && w[i+1] == 'u' {
			split = i + 2
			break
		}
		if c == 'y' && i > 0 {
			split = i
			break
		}
		if isVowel(c) {
			split = i
			break
		}
	}
	// Rule 2: move the consonant cluster to the end and add "ay".
	return w[split:] + w[:split] + "ay"
}

func isVowel(c byte) bool {
	switch c {
	case 'a', 'e', 'i', 'o', 'u':
		return true
	}
	return false
}

